const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], W = tok[1];
const dp = new Array(W + 1).fill(0);
for (let i = 0; i < n; i++) {
  const w = tok[2 + 2 * i], v = tok[3 + 2 * i];
  for (let c = W; c >= w; c--) if (dp[c - w] + v > dp[c]) dp[c] = dp[c - w] + v;
}
console.log(dp[W]);

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), W = sc.nextInt();
        long[] dp = new long[W + 1];
        for (int i = 0; i < n; i++) {
            int w = sc.nextInt();
            long v = sc.nextLong();
            for (int c = W; c >= w; c--) dp[c] = Math.max(dp[c], dp[c - w] + v);
        }
        System.out.println(dp[W]);
    }
}

solutions.cpp:
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, W;
    scanf("%d %d", &n, &W);
    vector<long long> dp(W + 1, 0);
    for (int i = 0; i < n; i++) {
        int w;
        long long v;
        scanf("%d %lld", &w, &v);
        for (int c = W; c >= w; c--) dp[c] = max(dp[c], dp[c - w] + v);
    }
    printf("%lld\n", dp[W]);
    return 0;
}
